import sys,json,numpy as np
from PIL import Image
sys.path.insert(0,sys.argv[3]); 
def lab(rgb):
  c=rgb/255.0; c=np.where(c>0.04045,((c+0.055)/1.055)**2.4,c/12.92)
  M=np.array([[0.4124,0.3576,0.1805],[0.2126,0.7152,0.0722],[0.0193,0.1192,0.9505]])
  xyz=c@M.T/np.array([0.95047,1.0,1.08883]); f=np.where(xyz>0.008856,np.cbrt(xyz),7.787*xyz+16/116)
  return np.stack([116*f[...,1]-16,500*(f[...,0]-f[...,1]),200*(f[...,1]-f[...,2])],-1)
im=np.asarray(Image.open(sys.argv[1]).convert('RGB')).astype(np.int32)
q=im>>3; key=(q[...,0]<<10)|(q[...,1]<<5)|q[...,2]
cnt=np.bincount(key.ravel(),minlength=1<<15); idx=np.nonzero(cnt)[0]; c=cnt[idx]; o=np.argsort(-c); idx=idx[o]; c=c[o]
rgb=np.stack([(idx>>10)&31,(idx>>5)&31,idx&31],1)*8+4; L=lab(rgb.astype(float)); tot=c.sum()
out={'pixels':int(tot),'distinct5bitBins':int(len(idx)),'distinctExact24bit':int(len(np.unique((im[...,0]<<16)|(im[...,1]<<8)|im[...,2])))}
def greedy(X,thr):
  pal=[];pc=[];pr=[]
  for x,n,r in zip(X,c,rgb):
    if pal:
      d=np.sqrt(((np.array(pal)-x)**2).sum(1)); j=d.argmin()
      if d[j]<=thr: pc[j]+=n; continue
    pal.append(x); pc.append(n); pr.append(r)
  pc=np.array(pc); oo=np.argsort(-pc); cs=np.cumsum(pc[oo])/tot
  return {'mergedColours':len(pal),'coloursFor90_95_99pct':[int(np.searchsorted(cs,t)+1) for t in (.9,.95,.99)],
          'top':[{'rgb':[int(v) for v in pr[k]],'pct':round(float(pc[k]/tot*100),2)} for k in oo[:12]]}
out['rgbEuclidGreedy']={str(t):greedy(rgb.astype(float),t) for t in (20,30,40)}
out['deltaE76Greedy']={str(t):greedy(L,t) for t in (5,10,20)}
for k in ('rgbEuclidGreedy','deltaE76Greedy'):
  for t,v in out[k].items():
    if t not in ('30','10'): v.pop('top')
json.dump(out,open(sys.argv[2],'w'),indent=1)
print(json.dumps({k:(v if not isinstance(v,dict) else {t:(x['mergedColours'],x['coloursFor90_95_99pct']) for t,x in v.items()}) for k,v in out.items()}))
